// ── HAPPY PUPS BACKYARD — Australian backyard, pup family, playground ──
// mt, w1, w2, w3, w, h, bY, bCol, wc, ol, isN, sc — runtime

// Sky
svg += `<defs>
  <linearGradient id="lg-pups" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${isN ? '#0A1628' : sc.sky1}"/>
    <stop offset="100%" stop-color="${isN ? '#1A2A48' : sc.sky2}"/>
  </linearGradient>
  <linearGradient id="lg-pups-house" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#E8D0A8"/>
    <stop offset="100%" stop-color="#D4B888"/>
  </linearGradient>
</defs>`;
svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="url(#lg-pups)"/>`;

// ── Clouds ──
for (let i = 0; i < 4; i++) {
  const clx = (w * 0.1 + i * w * 0.25 + mt * 8 + i * 50) % (w + 80) - 40;
  const cly = h * 0.08 + Math.sin(i * 2.3) * h * 0.04;
  const clr = 25 + Math.sin(i * 1.7) * 8;
  svg += `<ellipse cx="${clx}" cy="${cly}" rx="${clr}" ry="${clr*0.5}" fill="#FFF" opacity="${isN ? 0.15 : 0.7}"/>`;
  svg += `<ellipse cx="${clx-clr*0.5}" cy="${cly+3}" rx="${clr*0.7}" ry="${clr*0.4}" fill="#FFF" opacity="${isN ? 0.12 : 0.6}"/>`;
  svg += `<ellipse cx="${clx+clr*0.4}" cy="${cly+2}" rx="${clr*0.65}" ry="${clr*0.35}" fill="#FFF" opacity="${isN ? 0.12 : 0.55}"/>`;
}

// ── Green grass ground ──
svg += `<rect x="0" y="${bY-5}" width="${w}" height="${h-bY+5}" fill="${sc.ground}"/>`;
// Grass texture
for (let i = 0; i < 30; i++) {
  const gx = w * (i / 30);
  const gy = bY + Math.sin(i * 1.3) * 3;
  const gsway = Math.sin(mt * 1.2 + i * 0.7) * 2;
  svg += `<line x1="${gx}" y1="${gy}" x2="${gx+gsway}" y2="${gy-6-Math.sin(i*0.9)*3}" stroke="#5AA05A" stroke-width="1.5" stroke-linecap="round" opacity="0.5"/>`;
}
// Lighter grass patches
for (let i = 0; i < 8; i++) {
  const px2 = w * (0.05 + i * 0.12);
  svg += `<ellipse cx="${px2}" cy="${bY+15+Math.sin(i*2.1)*5}" rx="18" ry="5" fill="#8AD48A" opacity="0.3"/>`;
}

// ── QUEENSLANDER HOUSE (background, left side) ──
const hx = w * 0.12;
const hy = bY - 5;
const hw = w * 0.3;
const hh = 80;
// Stilts (Queenslander on stilts)
for (let i = 0; i < 4; i++) {
  svg += `<rect x="${hx + i * (hw/3) - 2}" y="${hy-10}" width="4" height="20" fill="#8B7355" stroke="#6B5335" stroke-width="${ol*0.3}"/>`;
}
// Main house body
svg += `<rect x="${hx-5}" y="${hy-hh}" width="${hw+10}" height="${hh-10}" rx="2" fill="url(#lg-pups-house)" stroke="#B8986A" stroke-width="${ol}"/>`;
// Veranda
svg += `<rect x="${hx-10}" y="${hy-hh+25}" width="${hw+20}" height="4" fill="#C8A878" stroke="#B8986A" stroke-width="${ol*0.4}"/>`;
// Veranda railing
for (let i = 0; i < 8; i++) {
  const rx = hx - 5 + i * ((hw+10)/8);
  svg += `<line x1="${rx}" y1="${hy-hh+29}" x2="${rx}" y2="${hy-hh+42}" stroke="#C8A878" stroke-width="1.5"/>`;
}
svg += `<line x1="${hx-8}" y1="${hy-hh+42}" x2="${hx+hw+8}" y2="${hy-hh+42}" stroke="#C8A878" stroke-width="2"/>`;
// Roof (tin roof — classic Queenslander)
svg += `<polygon points="${hx-15},${hy-hh} ${hx+hw/2},${hy-hh-30} ${hx+hw+15},${hy-hh}" fill="#8B4513" stroke="#6B3010" stroke-width="${ol}"/>`;
// Roof corrugation lines
for (let i = 0; i < 6; i++) {
  const rl = hx - 10 + i * ((hw+20)/6);
  svg += `<line x1="${rl}" y1="${hy-hh}" x2="${hx+hw/2}" y2="${hy-hh-28}" stroke="#7A3A10" stroke-width="0.5" opacity="0.4"/>`;
}
// Windows
for (let i = 0; i < 3; i++) {
  const wxp = hx + 10 + i * (hw * 0.32);
  const wyp = hy - hh + 35;
  const winPulse = Math.sin(mt * 1.5 + i * 1.9) * 0.5 + 0.5;
  svg += `<rect x="${wxp}" y="${wyp}" width="18" height="20" rx="1" fill="${isN ? `rgba(255,220,120,${0.4+winPulse*0.5})` : 'rgba(135,206,235,0.3)'}" stroke="#B8986A" stroke-width="${ol*0.5}"/>`;
  // Window cross
  svg += `<line x1="${wxp+9}" y1="${wyp}" x2="${wxp+9}" y2="${wyp+20}" stroke="#B8986A" stroke-width="1"/>`;
  svg += `<line x1="${wxp}" y1="${wyp+10}" x2="${wxp+18}" y2="${wyp+10}" stroke="#B8986A" stroke-width="1"/>`;
  if (isN) svg += `<ellipse cx="${wxp+9}" cy="${wyp+10}" rx="14" ry="12" fill="rgba(255,220,120,0.04)"/>`;
}
// Door
svg += `<rect x="${hx+hw*0.42}" y="${hy-hh+42}" width="14" height="25" rx="1" fill="#C45A3A" stroke="#8B3A1A" stroke-width="${ol*0.5}"/>`;
svg += `<circle cx="${hx+hw*0.42+11}" cy="${hy-hh+55}" r="1.5" fill="#FFD700"/>`;

// ── HILLS HOIST (iconic Australian clothesline) ──
const hlx = w * 0.55;
const hly = bY;
const hlh = 50;
// Pole
svg += `<line x1="${hlx}" y1="${hly}" x2="${hlx}" y2="${hly-hlh}" stroke="#888" stroke-width="3"/>`;
// Rotating arms (4 arms, slow spin)
const hlAngle = mt * 0.3;
for (let i = 0; i < 4; i++) {
  const a = hlAngle + i * (Math.PI / 2);
  const armLen = 28;
  // Perspective: foreshorten based on sin/cos
  const ex = hlx + Math.cos(a) * armLen;
  const ey = hly - hlh + Math.sin(a) * 8; // slight 3D perspective
  svg += `<line x1="${hlx}" y1="${hly-hlh}" x2="${ex}" y2="${ey}" stroke="#AAA" stroke-width="1.5"/>`;
  // Clothes hanging (little rectangles swaying)
  const clothSway = Math.sin(mt * 1.5 + i * 1.1) * 3;
  const clothColors = ['#FF6B6B','#4ECDC4','#FFD166','#9370DB'];
  svg += `<rect x="${(hlx+ex)/2 - 4}" y="${(hly-hlh+ey)/2}" width="8" height="6" rx="1" fill="${clothColors[i]}" opacity="0.8" transform="rotate(${clothSway} ${(hlx+ex)/2} ${(hly-hlh+ey)/2})"/>`;
}

// ── TRAMPOLINE ──
const tx = w * 0.75;
const ty = bY;
const tr = 30;
// Legs
svg += `<line x1="${tx-tr+5}" y1="${ty}" x2="${tx-tr+10}" y2="${ty-18}" stroke="#666" stroke-width="2"/>`;
svg += `<line x1="${tx+tr-5}" y1="${ty}" x2="${tx+tr-10}" y2="${ty-18}" stroke="#666" stroke-width="2"/>`;
// Mat (with bounce animation)
const bounce = Math.sin(mt * 3) * 2;
svg += `<ellipse cx="${tx}" cy="${ty-18+bounce}" rx="${tr}" ry="6" fill="#2A2A2A" stroke="#444" stroke-width="${ol*0.5}"/>`;
// Springs
for (let i = 0; i < 6; i++) {
  const sa = -Math.PI * 0.8 + i * (Math.PI * 1.6 / 5);
  svg += `<line x1="${tx+Math.cos(sa)*(tr-2)}" y1="${ty-18+bounce}" x2="${tx+Math.cos(sa)*(tr+3)}" y2="${ty-14}" stroke="#888" stroke-width="1"/>`;
}
// Safety net poles
svg += `<line x1="${tx-tr}" y1="${ty-18}" x2="${tx-tr}" y2="${ty-50}" stroke="#555" stroke-width="1.5"/>`;
svg += `<line x1="${tx+tr}" y1="${ty-18}" x2="${tx+tr}" y2="${ty-50}" stroke="#555" stroke-width="1.5"/>`;
svg += `<path d="M${tx-tr} ${ty-50} Q${tx} ${ty-45} ${tx+tr} ${ty-50}" fill="none" stroke="#888" stroke-width="1" stroke-dasharray="3,2"/>`;

// ── DOG FAMILY — 4 pups playing ──
// Parent dog (big blue heeler style)
const pdx = w * 0.48;
const pdy = bY - 3;
// Body
svg += `<ellipse cx="${pdx}" cy="${pdy-12}" rx="14" ry="10" fill="#5B8EC4" stroke="#3A6FA0" stroke-width="${ol*0.5}"/>`;
// Head
svg += `<circle cx="${pdx+12}" cy="${pdy-20}" r="8" fill="#5B8EC4" stroke="#3A6FA0" stroke-width="${ol*0.5}"/>`;
// Ears
svg += `<polygon points="${pdx+8},${pdy-26} ${pdx+6},${pdy-34} ${pdx+12},${pdy-28}" fill="#4A7AB0"/>`;
svg += `<polygon points="${pdx+16},${pdy-26} ${pdx+18},${pdy-34} ${pdx+14},${pdy-28}" fill="#4A7AB0"/>`;
// Eyes + nose
svg += `<circle cx="${pdx+10}" cy="${pdy-21}" r="1.5" fill="#222"/>`;
svg += `<circle cx="${pdx+15}" cy="${pdy-21}" r="1.5" fill="#222"/>`;
svg += `<ellipse cx="${pdx+12.5}" cy="${pdy-17}" rx="2" ry="1.5" fill="#222"/>`;
// Smile
svg += `<path d="M${pdx+10} ${pdy-16} Q${pdx+12.5} ${pdy-13} ${pdx+15} ${pdy-16}" fill="none" stroke="#222" stroke-width="1"/>`;
// Legs
for (let i = 0; i < 4; i++) {
  const lx = pdx - 8 + i * 5.5;
  svg += `<line x1="${lx}" y1="${pdy-4}" x2="${lx}" y2="${pdy+2}" stroke="#3A6FA0" stroke-width="2.5" stroke-linecap="round"/>`;
}
// Tail wag!
const tailWag = Math.sin(mt * 4) * 12;
svg += `<path d="M${pdx-14} ${pdy-14} Q${pdx-22} ${pdy-25+tailWag} ${pdx-18} ${pdy-30+tailWag*0.5}" fill="none" stroke="#5B8EC4" stroke-width="3" stroke-linecap="round"/>`;

// ── Pup 1 (small orange/red) — bouncing on trampoline ──
const p1x = tx;
const p1bounce = Math.abs(Math.sin(mt * 3)) * 20;
const p1y = ty - 24 - p1bounce;
// Body
svg += `<ellipse cx="${p1x}" cy="${p1y}" rx="8" ry="6" fill="#FF8C42" stroke="#D06B20" stroke-width="${ol*0.4}"/>`;
// Head
svg += `<circle cx="${p1x+6}" cy="${p1y-6}" r="5.5" fill="#FF8C42" stroke="#D06B20" stroke-width="${ol*0.4}"/>`;
// Ears
svg += `<polygon points="${p1x+3},${p1y-10} ${p1x+2},${p1y-16} ${p1x+6},${p1y-11}" fill="#E07830"/>`;
svg += `<polygon points="${p1x+9},${p1y-10} ${p1x+10},${p1y-16} ${p1x+7},${p1y-11}" fill="#E07830"/>`;
// Face
svg += `<circle cx="${p1x+5}" cy="${p1y-7}" r="1" fill="#222"/>`;
svg += `<circle cx="${p1x+8}" cy="${p1y-7}" r="1" fill="#222"/>`;
svg += `<ellipse cx="${p1x+6.5}" cy="${p1y-4.5}" rx="1.5" ry="1" fill="#222"/>`;
// Legs (spread in air)
const legSpread = p1bounce > 10 ? 3 : 0;
svg += `<line x1="${p1x-5}" y1="${p1y+4}" x2="${p1x-7-legSpread}" y2="${p1y+10}" stroke="#D06B20" stroke-width="2" stroke-linecap="round"/>`;
svg += `<line x1="${p1x+5}" y1="${p1y+4}" x2="${p1x+7+legSpread}" y2="${p1y+10}" stroke="#D06B20" stroke-width="2" stroke-linecap="round"/>`;

// ── Pup 2 (small purple/mauve) — chasing a ball ──
const p2run = (mt * 30) % (w * 0.25);
const p2x = w * 0.5 + p2run;
const p2y = bY + 15;
const p2bob = Math.sin(mt * 6) * 2;
// Body
svg += `<ellipse cx="${p2x}" cy="${p2y+p2bob}" rx="7" ry="5" fill="#9370DB" stroke="#7B5EA7" stroke-width="${ol*0.4}"/>`;
// Head
svg += `<circle cx="${p2x+5}" cy="${p2y-4+p2bob}" r="5" fill="#9370DB" stroke="#7B5EA7" stroke-width="${ol*0.4}"/>`;
// Ears
svg += `<polygon points="${p2x+2},${p2y-7+p2bob} ${p2x+1},${p2y-13+p2bob} ${p2x+5},${p2y-8+p2bob}" fill="#8060C0"/>`;
svg += `<polygon points="${p2x+8},${p2y-7+p2bob} ${p2x+9},${p2y-13+p2bob} ${p2x+6},${p2y-8+p2bob}" fill="#8060C0"/>`;
// Face
svg += `<circle cx="${p2x+4}" cy="${p2y-5+p2bob}" r="1" fill="#222"/>`;
svg += `<circle cx="${p2x+7}" cy="${p2y-5+p2bob}" r="1" fill="#222"/>`;
// Running legs
const p2leg = Math.sin(mt * 8) * 4;
svg += `<line x1="${p2x-4}" y1="${p2y+4+p2bob}" x2="${p2x-6+p2leg}" y2="${p2y+10}" stroke="#7B5EA7" stroke-width="2" stroke-linecap="round"/>`;
svg += `<line x1="${p2x+4}" y1="${p2y+4+p2bob}" x2="${p2x+6-p2leg}" y2="${p2y+10}" stroke="#7B5EA7" stroke-width="2" stroke-linecap="round"/>`;
// Ball ahead
const ballX = p2x + 18;
svg += `<circle cx="${ballX}" cy="${p2y+5+Math.abs(Math.sin(mt*4))*5}" r="4" fill="#FF4444" stroke="#CC2222" stroke-width="1"/>`;
svg += `<line x1="${ballX-2}" y1="${p2y+2+Math.abs(Math.sin(mt*4))*5}" x2="${ballX+2}" y2="${p2y+8+Math.abs(Math.sin(mt*4))*5}" stroke="#FFF" stroke-width="1" opacity="0.5"/>`;

// ── Pup 3 (small green) — sitting under tree ──
const p3x = w * 0.88;
const p3y = bY + 2;
// Body (sitting)
svg += `<ellipse cx="${p3x}" cy="${p3y-6}" rx="7" ry="8" fill="#5AAA5A" stroke="#3A8A3A" stroke-width="${ol*0.4}"/>`;
// Head
svg += `<circle cx="${p3x+2}" cy="${p3y-16}" r="5.5" fill="#5AAA5A" stroke="#3A8A3A" stroke-width="${ol*0.4}"/>`;
// Ears
svg += `<polygon points="${p3x-1},${p3y-20} ${p3x-2},${p3y-26} ${p3x+2},${p3y-21}" fill="#4A9A4A"/>`;
svg += `<polygon points="${p3x+5},${p3y-20} ${p3x+6},${p3y-26} ${p3x+3},${p3y-21}" fill="#4A9A4A"/>`;
// Sleepy eyes (closed)
svg += `<path d="M${p3x} ${p3y-17} Q${p3x+1.5} ${p3y-16} ${p3x+3} ${p3y-17}" fill="none" stroke="#222" stroke-width="1"/>`;
svg += `<path d="M${p3x+3} ${p3y-17} Q${p3x+4.5} ${p3y-16} ${p3x+6} ${p3y-17}" fill="none" stroke="#222" stroke-width="1"/>`;
// Z's (sleeping)
for (let i = 0; i < 3; i++) {
  const zx = p3x + 8 + i * 5;
  const zy = p3y - 22 - i * 8 + Math.sin(mt * 1.5 + i * 0.8) * 2;
  const zop = 0.3 + Math.sin(mt + i * 1.3) * 0.2;
  svg += `<text x="${zx}" y="${zy}" fill="#5B8EC4" font-size="${7+i*2}" font-weight="bold" opacity="${zop}">z</text>`;
}

// ── Eucalyptus trees ──
for (let i = 0; i < 3; i++) {
  const etx = w * 0.85 + i * 25;
  const eth = 60 + Math.sin(i * 2.7) * 15;
  const sway2 = Math.sin(mt * 0.6 + i * 1.1) * 2;
  // Trunk
  svg += `<rect x="${etx-3}" y="${bY-eth}" width="6" height="${eth}" rx="2" fill="#8B7355" stroke="#6B5335" stroke-width="${ol*0.3}"/>`;
  // Canopy (multiple overlapping circles for eucalyptus look)
  for (let j = 0; j < 4; j++) {
    const cx2 = etx + Math.sin(j * 1.8 + i) * 10 + sway2;
    const cy2 = bY - eth - 5 + Math.cos(j * 1.3) * 10;
    const cr = 10 + Math.sin(j * 2.1 + i * 0.7) * 5;
    svg += `<circle cx="${cx2}" cy="${cy2}" r="${cr}" fill="#4A8A5A" stroke="#3A6A3A" stroke-width="${ol*0.3}" opacity="0.75"/>`;
  }
}

// ── Garden elements ──
// Flower bed near house
for (let i = 0; i < 6; i++) {
  const fx = hx + hw + 15 + i * 12;
  const fy = bY + 3;
  const fColor = ['#FF6B9D','#FFD166','#FF6B6B','#DA70D6','#FF8C42','#4ECDC4'][i];
  const fSway = Math.sin(mt * 1.2 + i * 0.9) * 2;
  svg += `<line x1="${fx}" y1="${fy}" x2="${fx+fSway}" y2="${fy-10}" stroke="#4A8A4A" stroke-width="1.5"/>`;
  svg += `<circle cx="${fx+fSway}" cy="${fy-12}" r="3" fill="${fColor}"/>`;
  svg += `<circle cx="${fx+fSway}" cy="${fy-12}" r="1.5" fill="#FFD700" opacity="0.7"/>`;
}

// ── Fence (wooden picket) ──
svg += `<line x1="0" y1="${bY+30}" x2="${w}" y2="${bY+30}" stroke="#C8A878" stroke-width="2"/>`;
for (let i = 0; i < 20; i++) {
  const fxp = i * (w / 20) + w * 0.025;
  svg += `<rect x="${fxp}" y="${bY+22}" width="4" height="16" rx="1" fill="#D4B888" stroke="#B8986A" stroke-width="${ol*0.2}"/>`;
  svg += `<polygon points="${fxp},${bY+22} ${fxp+2},${bY+19} ${fxp+4},${bY+22}" fill="#D4B888" stroke="#B8986A" stroke-width="${ol*0.2}"/>`;
}

// ── Sun (day) / Moon + stars (night) ──
if (!isN) {
  svg += `<circle cx="${w * 0.85}" cy="${h * 0.12}" r="${35 + w1 * 8}" fill="#FFE082" opacity="0.15"/>`;
  svg += `<circle cx="${w * 0.85}" cy="${h * 0.12}" r="22" fill="#FFE082" opacity="0.55"/>`;
  // Sun rays
  for (let i = 0; i < 8; i++) {
    const ra = i * Math.PI / 4 + mt * 0.2;
    const rx1 = w * 0.85 + Math.cos(ra) * 28;
    const ry1 = h * 0.12 + Math.sin(ra) * 28;
    const rx2 = w * 0.85 + Math.cos(ra) * (35 + w1 * 5);
    const ry2 = h * 0.12 + Math.sin(ra) * (35 + w1 * 5);
    svg += `<line x1="${rx1}" y1="${ry1}" x2="${rx2}" y2="${ry2}" stroke="#FFE082" stroke-width="2" opacity="0.3" stroke-linecap="round"/>`;
  }
} else {
  svg += `<circle cx="${w * 0.82}" cy="${h * 0.12}" r="16" fill="#EDE8DF" opacity="0.85"/>`;
  svg += `<circle cx="${w * 0.82 + 5}" cy="${h * 0.12 - 4}" r="13" fill="#0A1628" opacity="0.9"/>`;
  // Stars
  for (let i = 0; i < 25; i++) {
    const stx = (Math.sin(i * 93.7 + 2.1) * 0.5 + 0.5) * w;
    const sty = (Math.sin(i * 217.3 + 5.7) * 0.5 + 0.5) * h * 0.35;
    const str = 0.5 + Math.sin(mt * 1.5 + i * 0.6) * 0.4;
    svg += `<circle cx="${stx}" cy="${sty}" r="${str}" fill="#FFF" opacity="${0.5 + Math.sin(mt+i)*0.3}"/>`;
  }
  // Fireflies in garden at night
  for (let i = 0; i < 8; i++) {
    const ffx = w * 0.3 + Math.sin(mt * 0.8 + i * 1.7) * w * 0.3;
    const ffy = bY - 10 + Math.cos(mt * 0.6 + i * 1.1) * 15;
    const ffop = 0.3 + Math.sin(mt * 2.5 + i * 1.3) * 0.3;
    svg += `<circle cx="${ffx}" cy="${ffy}" r="2" fill="#FFFF88" opacity="${ffop}"/>`;
    svg += `<circle cx="${ffx}" cy="${ffy}" r="5" fill="#FFFF88" opacity="${ffop*0.15}"/>`;
  }
}
